use miragex::crypto::keyfile::{
    apply_keyfiles, crc32_step, generate_keyfile, vc_keyfile_pool_size,
};

/// Deterministic 100-byte keyfile pattern used by the reference vectors.
fn pattern(len: usize) -> Vec<u8> {
    (0..len).map(|i| ((i * 7 + 13) & 0xff) as u8).collect()
}

/// Golden vectors generated by compiling the *official* VeraCrypt C code
/// (`KeyFileProcess` + `KeyFilesApply` from `src/Common/Keyfiles.c`,
/// CRC table from `src/Common/Crc.c`, whose selftest is 0x6FCF9E13).
/// These are byte-for-byte outputs of the C reference implementation.
#[test]
fn test_veracrypt_official_golden_vectors() {
    let kf1 = pattern(100);
    let kf2 = vec![0x55u8; 80];

    // No password, single keyfile -> 64-byte pool.
    assert_eq!(
        hex::encode(&*apply_keyfiles(b"", &[kf1.clone()]).unwrap()),
        "17dcdf1e61d6a30d734420ece6317c3da463e4ab4e030068f74bb9c8c5bdeb1d\
         f47f2531a05400611921fe1121ed9549bc85aaa7e086c7eca88259b49a90982b"
    );

    // 11-byte password, single keyfile -> 64-byte pool.
    assert_eq!(
        hex::encode(&*apply_keyfiles(b"password123", &[kf1.clone()]).unwrap()),
        "873d5291d8451571a47653ece6317c3da463e4ab4e030068f74bb9c8c5bdeb1d\
         f47f2531a05400611921fe1121ed9549bc85aaa7e086c7eca88259b49a90982b"
    );

    // Exactly 64-byte password -> legacy 64-byte pool.
    assert_eq!(
        hex::encode(&*apply_keyfiles(&[b'A'; 64], &[kf1.clone()]).unwrap()),
        "581d205fa217e44eb485612d2772bd7ee5a425ec8f4441a9388cfa0906fe2c5e\
         35c06672e19541a25a623f52622ed68afdc6ebe821c7082de9c39af5dbd1d96c"
    );

    // 65-byte password crosses the boundary -> 128-byte pool.
    assert_eq!(
        hex::encode(&*apply_keyfiles(&[b'B'; 65], &[kf1.clone()]).unwrap()),
        "19dcc37ed42ec4e44ae5b629d3e777b9b709bc5630aebbb7ee68070ff27b7ac4\
         e330cf56815762ea41d7141519411aa0bea8901e291f5e41a76bc132e38d4889\
         82425ee2cfea216b6ba1ac05558c47c62f9c6a97609787f34b25f4fb1584b39b\
         5391981d613fe0b91a8c2c3e4aeebdeb401f5ccbf9a9abed4359dac4f94592e4"
    );

    // 128-byte password -> 128-byte pool.
    assert_eq!(
        hex::encode(&*apply_keyfiles(&[b'C'; 128], &[kf1.clone()]).unwrap()),
        "1addc47fd52fc5e54be6b72ad4e878bab80abd5731afbcb8ef690810f37c7bc5\
         e431d057825863eb42d815161a421ba1bfa9911f2a205f42a86cc233e48e498a\
         8385a125122d64aeaee4ef4898cf8a0972dfaddaa3daca368e68373e58c7f6de\
         96d4db60a48223fc5dcf6f818d31002e83629f0e3cecee30869c1d073c88d527"
    );

    // 150-byte password: only the first 128 bytes are mixed, the rest is preserved.
    assert_eq!(
        hex::encode(&*apply_keyfiles(&[b'D'; 150], &[kf1.clone()]).unwrap()),
        "1bdec580d630c6e64ce7b82bd5e979bbb90bbe5832b0bdb9f06a0911f47d7cc6\
         e532d158835964ec43d916171b431ca2c0aa92202b216043a96dc334e58f4a8b\
         8486a226132e65afafe5f04999d08b0a73e0aedba4dbcb378f69383f59c8f7df\
         97d5dc61a58324fd5ed070828e32012f8463a00f3dedef31879d1e083d89d628\
         44444444444444444444444444444444444444444444"
    );

    // Two keyfiles are folded into the same pool, each resetting CRC/write pos.
    assert_eq!(
        hex::encode(&*apply_keyfiles(b"password123", &[kf1.clone(), kf2]).unwrap()),
        "6eee6e5e0160dc55326260c9571d219ec6a27fef0052b5c98bbac9c6877d5187\
         4d05dbac1890c7af7c2bbcf9513a0bd710b2fae1e7f713373feb16c2cdae76ab"
    );

    // Data beyond 1 MiB must be ignored (same result as the exact 1 MiB prefix).
    let big: Vec<u8> = (0..(1024 * 1024 + 1000))
        .map(|i| ((i * 31 + 7) & 0xff) as u8)
        .collect();
    let capped = apply_keyfiles(b"password123", &[big.clone()]).unwrap();
    let exact = apply_keyfiles(b"password123", &[big[..1024 * 1024].to_vec()]).unwrap();
    assert_eq!(&*capped, &*exact);
    assert_eq!(
        hex::encode(&*capped),
        "d6caa417142c181414455670fe6af8a20fea2718b98ed99fef7423e0b599ff18\
         8d36b664a690d1869f254d8bc84950b5532c58d4aae6bc59bd1020438c8dbab8"
    );
}

#[test]
fn test_crc32_step_equivalence() {
    // IEEE 802.3 check value for "123456789" (init 0xFFFFFFFF, final XOR 0xFFFFFFFF).
    let mut crc = 0xFFFFFFFFu32;
    for &b in b"123456789" {
        crc = crc32_step(crc, b);
    }
    assert_eq!(crc ^ 0xFFFFFFFF, 0xCBF43926);
}

#[test]
fn test_keyfile_pool_legacy_vs_modern_boundary() {
    let mut kf = vec![0u8; 100];
    for (i, b) in kf.iter_mut().enumerate() {
        *b = (i * 7 + 13) as u8;
    }

    // Passwords up to 64 bytes use 64-byte pool
    for len in 0..=64 {
        assert_eq!(vc_keyfile_pool_size(len), 64);
        let pwd = vec![0x42u8; len];
        let eff = apply_keyfiles(&pwd, &[kf.clone()]).unwrap();
        assert_eq!(eff.len(), 64);
    }

    // Passwords 65..=128 bytes use 128-byte pool
    for len in 65..=128 {
        assert_eq!(vc_keyfile_pool_size(len), 128);
        let pwd = vec![0x42u8; len];
        let eff = apply_keyfiles(&pwd, &[kf.clone()]).unwrap();
        assert_eq!(eff.len(), 128);
    }

    // Passwords > 128 bytes preserve original length
    let pwd_150 = vec![0x42u8; 150];
    let eff_150 = apply_keyfiles(&pwd_150, &[kf.clone()]).unwrap();
    assert_eq!(eff_150.len(), 150);
}

#[test]
fn test_multiple_keyfiles_combination() {
    let kf1 = vec![0xAA; 50];
    let kf2 = vec![0x55; 80];
    let pwd = b"supersecret";

    let eff1 = apply_keyfiles(pwd, &[kf1.clone()]).unwrap();
    let eff2 = apply_keyfiles(pwd, &[kf2.clone()]).unwrap();
    let eff_both = apply_keyfiles(pwd, &[kf1, kf2]).unwrap();

    assert_ne!(&*eff1, &*eff2);
    assert_ne!(&*eff_both, &*eff1);
    assert_ne!(&*eff_both, &*eff2);
}

#[test]
fn test_generate_keyfile_entropy() {
    let entropy_a = b"mouse_event_x_100_y_200";
    let entropy_b = b"mouse_event_x_101_y_200";

    let kf_a = generate_keyfile(64, Some(entropy_a)).unwrap();
    let kf_b = generate_keyfile(64, Some(entropy_b)).unwrap();

    assert_eq!(kf_a.len(), 64);
    assert_eq!(kf_b.len(), 64);
    assert_ne!(&*kf_a, &*kf_b);
}

#[test]
fn test_empty_keyfile_file_on_disk_is_rejected() {
    use miragex::crypto::keyfile::apply_keyfile_paths;
    let dir = std::env::temp_dir().join(format!("miragex_empty_kf_{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let empty = dir.join("empty.key");
    std::fs::write(&empty, b"").unwrap();

    assert!(apply_keyfile_paths(b"password", &[empty.as_path()]).is_err());

    let _ = std::fs::remove_dir_all(dir);
}
